let cart = [];
function addToCart(productName, price) {
    cart.push({
        name: productName,
        price: price
    });
    showToast(`${productName} added to cart!`, 'success');
    updateCartCount();
    console.log(cart);
}
function showCart() {
    let cartData = JSON.parse(localStorage.getItem('cart')) || [];
    if (cartData.length === 0) {
        showToast("Your cart is empty. Start shopping!", 'info');
        return;
    }
    window.location.href = 'cart.html';
}
function searchProduct() {
    let product = prompt("What are you looking for?");
    if (product) {
        window.location.href = `product-detail.html?search=${encodeURIComponent(product)}`;
    }
}
