async function loadStorefrontCatalog() {
    const grid = document.getElementById('productGrid');
    if (!grid) return;
    try {
        if (typeof apiRequest === 'function') {
            const data = await apiRequest('/products');
            allCatalogProducts = data.products || fallbackProducts;
        } else {
            allCatalogProducts = fallbackProducts;
        }
    } catch (err) {
        console.warn('Using fallback catalog:', err.message);
        allCatalogProducts = fallbackProducts;
    }
    renderCatalog();
}
function renderCatalog() {
    const grid = document.getElementById('productGrid');
    const noResults = document.getElementById('noResultsState');
    const countEl = document.getElementById('resultsCount');
    if (!grid) return;
    let filtered = [...allCatalogProducts];
    if (currentCategory && currentCategory !== 'all') {
        if (currentCategory === 'new') {
            filtered = filtered.filter(p => p.isNew || p.id <= 4);
        } else {
            filtered = filtered.filter(p => p.category && p.category.toLowerCase() === currentCategory.toLowerCase());
        }
    }
    if (currentSearch && currentSearch.trim()) {
        const query = currentSearch.trim().toLowerCase();
        filtered = filtered.filter(p =>
            (p.name && p.name.toLowerCase().includes(query)) ||
            (p.category && p.category.toLowerCase().includes(query)) ||
            (p.description && p.description.toLowerCase().includes(query))
        );
    }
    if (currentSort === 'price-asc') {
        filtered.sort((a, b) => a.price - b.price);
    } else if (currentSort === 'price-desc') {
        filtered.sort((a, b) => b.price - a.price);
    } else if (currentSort === 'rating') {
        filtered.sort((a, b) => (b.rating || 0) - (a.rating || 0));
    } else if (currentSort === 'newest') {
        filtered.sort((a, b) => (b.id || 0) - (a.id || 0));
    }
    if (countEl) {
        if (currentSearch) {
            countEl.textContent = `Showing ${filtered.length} results for "${currentSearch}"`;
        } else if (currentCategory !== 'all') {
            countEl.textContent = `Showing ${filtered.length} products in ${currentCategory}`;
        } else {
            countEl.textContent = `Showing all ${filtered.length} products`;
        }
    }
    if (filtered.length === 0) {
        grid.style.display = 'none';
        if (noResults) noResults.style.display = 'block';
        return;
    }
    grid.style.display = 'grid';
    if (noResults) noResults.style.display = 'none';
    grid.innerHTML = filtered.map(p => `
        <div class="product-card">
            <div class="product-image" onclick="viewProduct(${p.id})" style="background-image: url('${p.image}'); background-size: cover; background-position: center;">
                ${p.isNew || p.id <= 4 ? '<span>NEW</span>' : ''}
            </div>
            <div class="product-info" style="padding: 16px;">
                <span style="font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #888; font-weight: 700;">${p.category}</span>
                <h3 style="margin: 6px 0 4px 0; font-size: 16px;"><a href="product-detail.html?id=${p.id}" style="color: inherit; text-decoration: none;">${p.name}</a></h3>
                <p style="color: #f59e0b; font-size: 12px; margin: 4px 0 8px 0; font-weight: 600;">
                    ★ ${p.rating || '4.8'} <span style="color: #888; font-weight: normal;">(${p.reviewCount || 2})</span>
                </p>
                <h4 style="font-size: 16px; margin-bottom: 12px;">
                    ₹${Number(p.price).toLocaleString('en-IN')}
                    ${p.originalPrice ? `<span style="font-size: 12px; color: #888; text-decoration: line-through; font-weight: normal; margin-left: 6px;">₹${Number(p.originalPrice).toLocaleString('en-IN')}</span>` : ''}
                </h4>
                <div style="display: flex; gap: 8px;">
                    <button type="button" onclick="viewProduct(${p.id})" style="flex: 1; padding: 10px; font-size: 12px; font-weight: 600;">VIEW DETAILS</button>
                    <button type="button" onclick="quickAddToCart(event, ${p.id})" class="quick-cart-btn" title="Add to Cart">🛒</button>
                </div>
            </div>
        </div>
    `).join('');
}
function handleSearchInput(event) {
    currentSearch = event.target.value;
    const clearBtn = document.getElementById('clearSearchBtn');
    if (clearBtn) {
        clearBtn.style.display = currentSearch ? 'block' : 'none';
    }
    renderCatalog();
}
function clearCatalogSearch() {
    currentSearch = '';
    const input = document.getElementById('catalogSearchInput');
    if (input) input.value = '';
    const clearBtn = document.getElementById('clearSearchBtn');
    if (clearBtn) clearBtn.style.display = 'none';
    renderCatalog();
}
function handleSortChange(event) {
    currentSort = event.target.value;
    renderCatalog();
}
function filterCategory(category) {
    currentCategory = category;
    document.querySelectorAll('.catalog-category-tabs .cat-pill').forEach(btn => {
        if (btn.dataset.category.toLowerCase() === category.toLowerCase()) {
            btn.classList.add('active');
        } else {
            btn.classList.remove('active');
        }
    });
    renderCatalog();
    const catalogEl = document.getElementById('catalog');
    if (catalogEl) {
        catalogEl.scrollIntoView({ behavior: 'smooth' });
    }
}
function resetFilters() {
    currentCategory = 'all';
    currentSearch = '';
    currentSort = 'featured';
    const searchInput = document.getElementById('catalogSearchInput');
    if (searchInput) searchInput.value = '';
    const clearBtn = document.getElementById('clearSearchBtn');
    if (clearBtn) clearBtn.style.display = 'none';
    const sortSelect = document.getElementById('catalogSortSelect');
    if (sortSelect) sortSelect.value = 'featured';
    document.querySelectorAll('.catalog-category-tabs .cat-pill').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.category === 'all');
    });
    renderCatalog();
}
function focusCatalogSearch() {
    const input = document.getElementById('catalogSearchInput');
    if (input) {
        input.scrollIntoView({ behavior: 'smooth', block: 'center' });
        input.focus();
    }
}
function quickAddToCart(event, productId) {
    event.stopPropagation();
    const product = allCatalogProducts.find(p => p.id === productId);
    if (!product) return;
    let cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const existing = cart.find(item => (item.id || item.productId) === productId);
    if (existing) {
        existing.quantity = (existing.quantity || 1) + 1;
    } else {
        cart.push({
            id: product.id,
            productId: product.id,
            name: product.name,
            price: product.price,
            image: product.image,
            color: 'Black',
            size: 'M',
            quantity: 1
        });
    }
    localStorage.setItem('cart', JSON.stringify(cart));
    if (typeof showToast === 'function') {
        showToast(`${product.name} added to cart!`, 'success');
    } else {
        alert(`${product.name} added to cart!`);
    }
    if (typeof updateCartCount === 'function') {
        updateCartCount();
    }
}
